import { cn } from "@/lib/cn";
import Link from "next/link";
import type { ButtonHTMLAttributes, ReactNode } from "react";

type Variant = "gold" | "outline" | "ghost" | "cream" | "outlineLight";
type Size = "sm" | "md" | "lg";

const variants: Record<Variant, string> = {
  gold: "bg-gold text-charcoal hover:bg-gold-light shadow-gold",
  outline:
    "border border-gold/70 text-charcoal hover:bg-gold hover:text-charcoal",
  outlineLight:
    "border border-gold/80 text-cream hover:bg-gold hover:text-charcoal",
  ghost: "text-cream hover:text-gold",
  cream: "bg-cream text-charcoal hover:bg-white",
};

const sizes: Record<Size, string> = {
  sm: "px-4 py-2 text-xs tracking-[0.16em]",
  md: "px-6 py-3 text-[0.7rem] tracking-[0.18em]",
  lg: "px-8 py-3.5 text-xs tracking-[0.2em]",
};

type ButtonProps = {
  variant?: Variant;
  size?: Size;
  href?: string;
  className?: string;
  children: ReactNode;
} & ButtonHTMLAttributes<HTMLButtonElement>;

export function Button({
  variant = "gold",
  size = "md",
  href,
  className,
  children,
  type = "button",
  ...props
}: ButtonProps) {
  const classes = cn(
    "inline-flex items-center justify-center gap-2 uppercase font-medium transition-all duration-300 ease-out",
    "hover:-translate-y-0.5 active:translate-y-0",
    variants[variant],
    sizes[size],
    className,
  );

  if (href) {
    return (
      <Link href={href} className={classes}>
        {children}
      </Link>
    );
  }

  return (
    <button type={type} className={classes} {...props}>
      {children}
    </button>
  );
}

import { cn } from "@/lib/cn";
import type { HTMLAttributes, ReactNode } from "react";

type CardProps = HTMLAttributes<HTMLDivElement> & {
  children: ReactNode;
  hover?: boolean;
  padded?: boolean;
};

export function Card({
  children,
  className,
  hover = true,
  padded = true,
  ...props
}: CardProps) {
  return (
    <div
      className={cn(
        "bg-white text-charcoal border border-transparent",
        padded && "p-8 md:p-10",
        hover &&
          "transition-all duration-500 hover:-translate-y-1 hover:border-gold/70 hover:shadow-lift",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

"use client";

import { cn } from "@/lib/cn";
import { motion } from "framer-motion";

type TabItem = {
  id: string;
  label: string;
};

type TabsProps = {
  tabs: TabItem[];
  value: string;
  onChange: (id: string) => void;
  ariaLabel: string;
  variant?: "light" | "dark" | "gold";
  layoutId?: string;
};

export function Tabs({
  tabs,
  value,
  onChange,
  ariaLabel,
  variant = "dark",
  layoutId = "tab-underline",
}: TabsProps) {
  const isDark = variant === "dark";
  const isGold = variant === "gold";

  return (
    <div
      role="tablist"
      aria-label={ariaLabel}
      className={cn(
        "relative inline-flex items-center gap-1",
        isGold && "w-full rounded-none bg-charcoal/40 p-1 backdrop-blur-md sm:w-auto",
      )}
    >
      {tabs.map((tab) => {
        const selected = tab.id === value;
        return (
          <button
            key={tab.id}
            type="button"
            role="tab"
            id={`tab-${tab.id}`}
            aria-selected={selected}
            aria-controls={`panel-${tab.id}`}
            tabIndex={selected ? 0 : -1}
            onClick={() => onChange(tab.id)}
            className={cn(
              "relative px-5 py-2.5 text-[0.7rem] uppercase tracking-[0.2em] transition-colors duration-300",
              isGold && "flex-1 sm:flex-none",
              selected
                ? isDark
                  ? "text-charcoal"
                  : "text-gold"
                : isDark
                  ? "text-ink-muted hover:text-charcoal"
                  : "text-cream/70 hover:text-cream",
            )}
          >
            {selected && (
              <motion.span
                layoutId={layoutId}
                className={cn(
                  "absolute inset-x-2 -bottom-px h-px",
                  isGold
                    ? "inset-0 h-auto bg-gold/20 ring-1 ring-gold/60"
                    : "bg-gold",
                )}
                transition={{ type: "spring", stiffness: 380, damping: 30 }}
              />
            )}
            <span className="relative z-10">{tab.label}</span>
          </button>
        );
      })}
    </div>
  );
}

"use client";

import { cn } from "@/lib/cn";
import { motion, useReducedMotion } from "framer-motion";
import type { ReactNode } from "react";

type FadeInProps = {
  children: ReactNode;
  className?: string;
  delay?: number;
  y?: number;
};

export function FadeIn({ children, className, delay = 0, y = 28 }: FadeInProps) {
  const reduce = useReducedMotion();

  return (
    <motion.div
      className={cn(className)}
      initial={reduce ? false : { opacity: 0, y }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.2 }}
      transition={{ duration: 0.7, delay, ease: [0.22, 1, 0.36, 1] }}
    >
      {children}
    </motion.div>
  );
}

import { cn } from "@/lib/cn";

type SectionHeadingProps = {
  eyebrow?: string;
  title: string;
  description?: string;
  align?: "left" | "center";
  light?: boolean;
};

export function SectionHeading({
