}

"use client";

import { Button } from "@/components/ui/Button";
import { navLinks } from "@/data/site";
import { cn } from "@/lib/cn";
import { AnimatePresence, motion } from "framer-motion";
import { Menu, X } from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";

export function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  return (
    <header
      className={cn(
        "fixed inset-x-0 top-0 z-50 transition-all duration-500",
        scrolled || open
          ? "bg-charcoal/95 shadow-[0_10px_40px_rgba(0,0,0,0.28)] backdrop-blur-md"
          : "bg-transparent",
      )}
    >
      <a
        href="#main"
        className="sr-only focus:not-sr-only focus:absolute focus:left-4 focus:top-4 focus:z-50 focus:bg-gold focus:px-4 focus:py-2 focus:text-charcoal"
      >
        Skip to content
      </a>
      <div className="mx-auto flex max-w-wide items-center justify-between px-5 py-4 md:px-8">
        <Link
          href="#top"
          className="font-serif text-lg tracking-[0.22em] text-cream md:text-xl"
        >
          LUXE <span className="text-gold">ESTATES</span>
        </Link>

        <nav className="hidden items-center gap-8 lg:flex" aria-label="Primary">
          {navLinks.map((link) => (
            <Link
              key={link.href}
              href={link.href}
              className="text-[0.68rem] uppercase tracking-[0.22em] text-cream/80 transition-colors hover:text-gold"
            >
              {link.label}
            </Link>
          ))}
        </nav>

        <div className="hidden lg:block">
          <Button href="#contact" size="sm">
            Get Started
          </Button>
        </div>

        <button
          type="button"
          className="text-cream lg:hidden"
          aria-expanded={open}
          aria-controls="mobile-nav"
          aria-label={open ? "Close menu" : "Open menu"}
          onClick={() => setOpen((v) => !v)}
        >
          {open ? <X size={22} /> : <Menu size={22} />}
        </button>
      </div>

      <AnimatePresence>
        {open ? (
          <motion.nav
            id="mobile-nav"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="overflow-hidden border-t border-white/10 lg:hidden"
            aria-label="Mobile"
          >
            <div className="flex flex-col gap-5 px-6 py-8">
              {navLinks.map((link) => (
                <Link
                  key={link.href}
                  href={link.href}
                  onClick={() => setOpen(false)}
                  className="text-sm uppercase tracking-[0.22em] text-cream"
                >
                  {link.label}
                </Link>
              ))}
              <Button href="#contact" onClick={() => setOpen(false)}>
                Get Started
              </Button>
            </div>
          </motion.nav>
        ) : null}
      </AnimatePresence>
    </header>
  );
}

"use client";

import { Button } from "@/components/ui/Button";
import { Tabs } from "@/components/ui/Tabs";
import { bedroomOptions, heroImage, priceRanges, propertyTypes } from "@/data/site";
import { AnimatePresence, motion } from "framer-motion";
import { Search } from "lucide-react";
import Image from "next/image";
import { FormEvent, useState } from "react";

const intentTabs = [
  { id: "buy", label: "Buy" },
  { id: "rent", label: "Rent" },
  { id: "sell", label: "Sell" },
  { id: "list", label: "List for Rent" },
];

type Intent = (typeof intentTabs)[number]["id"];

export function Hero() {
  const [intent, setIntent] = useState<Intent>("buy");
  const isSearch = intent === "buy" || intent === "rent";

  const onSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
  };

  return (
    <section id="top" className="relative isolate min-h-screen overflow-hidden">
      <Image
        src={heroImage}
        alt="Luxury hillside villa with a private infinity pool at twilight"
        fill
        priority
        className="object-cover"
        sizes="100vw"
      />
      <div className="absolute inset-0 bg-gradient-to-b from-charcoal/70 via-charcoal/55 to-charcoal/85" />
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_0%,rgba(26,26,26,0.45)_70%)]" />

      <div className="relative z-10 mx-auto flex min-h-screen max-w-wide flex-col items-center justify-center px-5 pb-16 pt-28 text-center md:px-8">
        <motion.p
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7 }}
          className="mb-5 text-[0.68rem] uppercase tracking-[0.4em] text-gold"
        >
          Private Client Real Estate
        </motion.p>
        <motion.h1
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.1 }}
          className="max-w-4xl font-serif text-4xl leading-[1.15] text-cream sm:text-5xl md:text-6xl lg:text-7xl"
        >
          Where Exceptional Homes Meet Exceptional People
        </motion.h1>
        <motion.p
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.2 }}
          className="mt-6 max-w-xl text-base text-cream/75 md:text-lg"
        >
          Discover, buy, rent, or list the world&apos;s most prestigious
          properties.
        </motion.p>

        <motion.div
          initial={{ opacity: 0, y: 32 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.85, delay: 0.32 }}
          className="mt-10 w-full max-w-4xl"
        >
          <div className="flex justify-center">
            <Tabs
              tabs={intentTabs}
              value={intent}
              onChange={(id) => setIntent(id as Intent)}
              ariaLabel="Choose whether you want to buy, rent, sell, or list a property"
              variant="gold"
              layoutId="hero-intent-tab"
            />
          </div>

          <div
            role="tabpanel"
            id={`panel-${intent}`}
            aria-labelledby={`tab-${intent}`}
            className="mt-4 border border-white/10 bg-charcoal/55 p-5 text-left shadow-lift backdrop-blur-xl md:p-7"
          >
            <AnimatePresence mode="wait">
              {isSearch ? (
                <motion.form
                  key={intent}
                  onSubmit={onSubmit}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  className="grid gap-4 md:grid-cols-2 lg:grid-cols-5"
                >
                  <Field label="Location" htmlFor={`${intent}-location`}>
                    <input
                      id={`${intent}-location`}
                      name="location"
                      placeholder="City, neighborhood, or region"
                      className="field-input"
                    />
                  </Field>
                  <Field label="Property Type" htmlFor={`${intent}-type`}>
                    <select id={`${intent}-type`} name="type" className="field-input">
                      <option value="">Any</option>
                      {propertyTypes.map((type) => (
                        <option key={type}>{type}</option>
                      ))}
                    </select>
                  </Field>
                  <Field label="Price Range" htmlFor={`${intent}-price`}>
                    <select id={`${intent}-price`} name="price" className="field-input">
                      {priceRanges[intent].map((range) => (
                        <option key={range}>{range}</option>
                      ))}
                    </select>
                  </Field>
                  <Field label="Bedrooms" htmlFor={`${intent}-beds`}>
                    <select id={`${intent}-beds`} name="beds" className="field-input">
                      {bedroomOptions.map((beds) => (
                        <option key={beds}>{beds}</option>
                      ))}
                    </select>
                  </Field>
                  <div className="flex items-end">
                    <Button type="submit" className="w-full" size="lg">
                      <Search size={16} aria-hidden />
                      Search
                    </Button>
                  </div>
                </motion.form>
              ) : (
                <motion.form
                  key={intent}
                  onSubmit={onSubmit}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  className="grid gap-4 md:grid-cols-[1fr_auto]"
                >
                  <Field
                    label="Tell us about your property"
                    htmlFor={`${intent}-details`}
                  >
                    <textarea
                      id={`${intent}-details`}
                      name="details"
                      rows={3}
                      placeholder="Location, property type, and what you hope to achieve."
                      className="field-input min-h-[88px] resize-none"
                    />
                  </Field>
                  <div className="flex items-end">
                    <Button type="submit" className="w-full whitespace-nowrap" size="lg">
                      Get Valuation
                    </Button>
                  </div>
                </motion.form>
              )}
            </AnimatePresence>
          </div>
        </motion.div>
      </div>
    </section>
  );
}

function Field({
  label,
  htmlFor,
  children,
}: {
  label: string;
  htmlFor: string;
  children: React.ReactNode;
}) {
  return (
    <label htmlFor={htmlFor} className="block">
      <span className="mb-2 block text-[0.62rem] uppercase tracking-[0.2em] text-gold/90">
        {label}
      </span>
      {children}
    </label>
  );
}

