"use client";

import { PropertyCard } from "@/components/PropertyCard";
import { FadeIn } from "@/components/ui/FadeIn";
import { SectionHeading } from "@/components/ui/SectionHeading";
import { Tabs } from "@/components/ui/Tabs";
import { properties, type ListingIntent } from "@/data/properties";
import { useMemo, useState } from "react";

const listingTabs = [
  { id: "sale", label: "For Sale" },
  { id: "rent", label: "For Rent" },
];

export function FeaturedProperties() {
  const [intent, setIntent] = useState<ListingIntent>("sale");

  const listings = useMemo(
    () => properties.filter((property) => property.intent === intent).slice(0, 6),
    [intent],
  );

  return (
    <section
      id={intent === "sale" ? "listings" : "rent"}
      className="bg-white py-20 md:py-28"
      aria-labelledby="featured-heading"
    >
      <div className="mx-auto max-w-wide px-5 md:px-8">
        <FadeIn>
          <div className="flex flex-col items-center gap-8">
            <SectionHeading
              eyebrow="The Collection"
              title="Featured Listings"
              description="A considered edit of residences currently available to acquire or lease."
            />
            <Tabs
              tabs={listingTabs}
              value={intent}
              onChange={(id) => setIntent(id as ListingIntent)}
              ariaLabel="Filter featured listings by sale or rent"
              variant="dark"
              layoutId="featured-tab"
            />
          </div>
        </FadeIn>

        <div
          role="tabpanel"
          id={`panel-${intent}`}
          aria-labelledby={`tab-${intent}`}
          className="mt-12 grid grid-cols-1 gap-7 sm:grid-cols-2 lg:grid-cols-3"
        >
          {listings.map((property, index) => (
            <FadeIn key={property.id} delay={index * 0.05}>
              <PropertyCard property={property} />
            </FadeIn>
          ))}
        </div>
      </div>
    </section>
  );
}

