import { createClient, type SupabaseClient } from "@supabase/supabase-js";

function assertServerOnly() {
  if (typeof window !== "undefined") {
    throw new Error(
      "supabaseAdmin is server-only. Do not import it in client components.",
    );
  }
}

function getUrl() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  if (!url) {
    throw new Error("Missing NEXT_PUBLIC_SUPABASE_URL");
  }
  return url;
}

function createAdminClient(): SupabaseClient {
  assertServerOnly();
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!key) {
    throw new Error("Missing SUPABASE_SERVICE_ROLE_KEY");
  }
  return createClient(getUrl(), key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

function createPublicClient(): SupabaseClient {
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  if (!key) {
    throw new Error("Missing NEXT_PUBLIC_SUPABASE_ANON_KEY");
  }
  return createClient(getUrl(), key);
}

let adminClient: SupabaseClient | undefined;
let publicClient: SupabaseClient | undefined;

export const supabaseAdmin: SupabaseClient = new Proxy({} as SupabaseClient, {
  get(_target, prop, receiver) {
    if (!adminClient) {
      adminClient = createAdminClient();
    }
    const value = Reflect.get(adminClient, prop, receiver);
    return typeof value === "function" ? value.bind(adminClient) : value;
  },
});

export const supabasePublic: SupabaseClient = new Proxy({} as SupabaseClient, {
  get(_target, prop, receiver) {
    if (!publicClient) {
      publicClient = createPublicClient();
    }
    const value = Reflect.get(publicClient, prop, receiver);
    return typeof value === "function" ? value.bind(publicClient) : value;
  },
});

import crypto from "crypto";
import Razorpay from "razorpay";

function assertServerOnly() {
  if (typeof window !== "undefined") {
    throw new Error("lib/razorpay.ts is server-only.");
  }
}

function getSecret() {
  if (process.env.NEXT_PUBLIC_RAZORPAY_KEY_SECRET) {
    throw new Error("Do not expose Razorpay secrets via NEXT_PUBLIC_ env vars.");
  }
  const secret = process.env.RAZORPAY_KEY_SECRET;
  if (!secret) {
    throw new Error("Missing RAZORPAY_KEY_SECRET");
  }
  return secret;
}

function getKeyId() {
  if (process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID && !process.env.RAZORPAY_KEY_ID) {
    throw new Error(
      "Use RAZORPAY_KEY_ID on the server. NEXT_PUBLIC_RAZORPAY_KEY_ID is for checkout only.",
    );
  }
  const keyId = process.env.RAZORPAY_KEY_ID;
  if (!keyId) {
    throw new Error("Missing RAZORPAY_KEY_ID");
  }
  return keyId;
}

let client: Razorpay | undefined;

function getClient() {
  assertServerOnly();
  if (!client) {
    client = new Razorpay({
      key_id: getKeyId(),
      key_secret: getSecret(),
    });
  }
  return client;
}

export async function createOrder({
  amount,
  receipt,
  notes,
}: {
  amount: number;
  receipt: string;
  notes?: Record<string, string>;
}) {
  return getClient().orders.create({
    amount,
    currency: "INR",
    receipt,
    notes,
  });
}

export function verifySignature({
  orderId,
  paymentId,
  signature,
}: {
  orderId: string;
  paymentId: string;
  signature: string;
}) {
  assertServerOnly();
  const expected = crypto
    .createHmac("sha256", getSecret())
    .update(`${orderId}|${paymentId}`)
    .digest("hex");
  return expected === signature;
}

export async function createRefund({
  paymentId,
  amount,
  notes,
}: {
  paymentId: string;
  amount: number;
  notes?: Record<string, string>;
}) {
  return getClient().payments.refund(paymentId, {
    amount,
    notes,
  });
}

export function verifyWebhookSignature(rawBody: string, signature: string) {
  assertServerOnly();
  const secret = process.env.RAZORPAY_WEBHOOK_SECRET;
  if (!secret) {
    throw new Error("Missing RAZORPAY_WEBHOOK_SECRET");
  }
  const expected = crypto
    .createHmac("sha256", secret)
    .update(rawBody)
    .digest("hex");
  return expected === signature;
}

import { z } from "zod";

export const VIEWING_SLOTS = [
  "10:00",
  "11:00",
  "12:00",
  "14:00",
  "15:00",
  "16:00",
  "17:00",
] as const;

export const bookingSchema = z.object({
  clientName: z.string().min(2).max(100),
  clientPhone: z
    .string()
    .regex(/^[6-9]\d{9}$/, "Enter a valid 10-digit Indian mobile number"),
  clientEmail: z.string().email(),
  propertyId: z.string().min(1),
  propertyTitle: z.string().min(1),
  viewingDate: z
    .string()
    .refine((d) => new Date(d) > new Date(), "Date must be in the future"),
  viewingSlot: z.enum(VIEWING_SLOTS),
  termsAccepted: z.literal(true),
});

export type BookingInput = z.infer<typeof bookingSchema>;

export type BookingStatus =
  | "pending_payment"
  | "confirmed"
  | "failed"
  | "cancelled";

export type BookingOutcome =
  | "pending"
  | "completed"
  | "client_noshow"
  | "team_noshow"
  | "cancelled";

export type RefundStatus =
  | "none"
  | "requested"
  | "processing"
  | "refunded"
  | "failed";

export type Booking = {
  id: string;
  client_phone: string;
  client_name: string;
  client_email: string;
  property_id: string;
  property_title: string;
  viewing_date: string;
  viewing_slot: string;
  amount: number;
  status: BookingStatus;
  outcome: BookingOutcome | null;
  razorpay_order_id: string | null;
  razorpay_payment_id: string | null;
  razorpay_signature: string | null;
  refund_status: RefundStatus | null;
  refund_id: string | null;
  refund_reason: string | null;
