import { sendRefundConfirmationToClient } from "@/lib/email";
import { createRefund } from "@/lib/razorpay";
import { BOOKING_FEE_PAISE, type Booking } from "@/lib/schemas";
import { supabaseAdmin } from "@/lib/supabase";

export async function processTeamNoShowRefund(
  booking: Booking,
  reason = "Team failed to arrive within 20 minutes of the scheduled viewing.",
) {
  if (booking.status !== "confirmed") {
    throw new Error("Only confirmed bookings can be refunded.");
  }
  if (booking.outcome === "completed") {
    throw new Error("Completed viewings cannot be refunded.");
  }
  if (booking.refund_status === "refunded") {
    return { booking, refund: { id: booking.refund_id } };
  }
  if (!booking.razorpay_payment_id) {
    throw new Error("Missing Razorpay payment id.");
  }

  const refund = await createRefund({
    paymentId: booking.razorpay_payment_id,
    amount: BOOKING_FEE_PAISE,
    notes: { reason, bookingId: booking.id },
  });

  const { data, error } = await supabaseAdmin
    .from("bookings")
    .update({
      refund_status: "refunded",
      refund_id: refund.id,
      refund_reason: reason,
      outcome: "team_noshow",
    })
    .eq("id", booking.id)
    .select()
    .single();

  if (error) {
    throw new Error(error.message);
  }

  const updated = data as Booking;
  await sendRefundConfirmationToClient(updated, refund.id).catch(() => undefined);

  return { booking: updated, refund };
}

import { createOrder } from "@/lib/razorpay";
import { BOOKING_FEE_PAISE, BOOKING_FEE_RUPEES, bookingSchema } from "@/lib/schemas";
import { supabaseAdmin } from "@/lib/supabase";
import { NextResponse } from "next/server";

export async function POST(request: Request) {
  try {
    const json = await request.json();
    const parsed = bookingSchema.safeParse(json);

    if (!parsed.success) {
      return NextResponse.json(
        { error: "Invalid booking details", issues: parsed.error.flatten() },
        { status: 400 },
      );
    }

    const input = parsed.data;

    const { data: existing, error: existingError } = await supabaseAdmin
      .from("bookings")
      .select("id")
      .eq("client_phone", input.clientPhone)
      .eq("property_id", input.propertyId)
      .eq("viewing_date", input.viewingDate)
      .eq("viewing_slot", input.viewingSlot)
      .eq("status", "confirmed")
      .maybeSingle();

    if (existingError) {
      return NextResponse.json({ error: existingError.message }, { status: 500 });
    }

    if (existing) {
      return NextResponse.json(
        {
          error:
            "You already have a confirmed viewing for this property at this date and time.",
        },
        { status: 409 },
      );
    }

    const { data: booking, error: insertError } = await supabaseAdmin
      .from("bookings")
      .insert({
        client_phone: input.clientPhone,
        client_name: input.clientName,
        client_email: input.clientEmail,
        property_id: input.propertyId,
        property_title: input.propertyTitle,
        viewing_date: input.viewingDate,
        viewing_slot: input.viewingSlot,
        amount: BOOKING_FEE_RUPEES,
        status: "pending_payment",
        outcome: "pending",
      })
      .select()
      .single();

    if (insertError || !booking) {
      return NextResponse.json(
        { error: insertError?.message ?? "Could not create booking" },
        { status: 500 },
      );
    }

    const order = await createOrder({
      amount: BOOKING_FEE_PAISE,
      receipt: booking.id,
      notes: {
        bookingId: booking.id,
        propertyId: input.propertyId,
        clientPhone: input.clientPhone,
      },
    });

    const { error: updateError } = await supabaseAdmin
      .from("bookings")
      .update({ razorpay_order_id: order.id })
      .eq("id", booking.id);

    if (updateError) {
      return NextResponse.json({ error: updateError.message }, { status: 500 });
    }

    const key = process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID;
    if (!key) {
      return NextResponse.json(
        { error: "Missing NEXT_PUBLIC_RAZORPAY_KEY_ID" },
        { status: 500 },
      );
    }

    return NextResponse.json({
      bookingId: booking.id,
      orderId: order.id,
      amount: BOOKING_FEE_PAISE,
      currency: "INR",
      key,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Booking failed";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import {
  sendBookingAlertToTeam,
  sendBookingConfirmationToClient,
} from "@/lib/email";
import { verifySignature } from "@/lib/razorpay";
import type { Booking } from "@/lib/schemas";
import { supabaseAdmin } from "@/lib/supabase";
import { NextResponse } from "next/server";

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const {
      bookingId,
      razorpay_order_id,
      razorpay_payment_id,
      razorpay_signature,
    } = body as {
      bookingId?: string;
      razorpay_order_id?: string;
      razorpay_payment_id?: string;
      razorpay_signature?: string;
    };

    if (
      !bookingId ||
      !razorpay_order_id ||
      !razorpay_payment_id ||
      !razorpay_signature
    ) {
      return NextResponse.json({ error: "Missing payment fields" }, { status: 400 });
    }

    const valid = verifySignature({
      orderId: razorpay_order_id,
      paymentId: razorpay_payment_id,
      signature: razorpay_signature,
    });

    if (!valid) {
      await supabaseAdmin
        .from("bookings")
        .update({ status: "failed" })
        .eq("id", bookingId);
      return NextResponse.json({ error: "Invalid payment signature" }, { status: 400 });
    }

    const { data, error } = await supabaseAdmin
      .from("bookings")
      .update({
        status: "confirmed",
        razorpay_order_id,
        razorpay_payment_id,
        razorpay_signature,
      })
      .eq("id", bookingId)
      .select()
      .single();

    if (error || !data) {
      return NextResponse.json(
        { error: error?.message ?? "Could not confirm booking" },
        { status: 500 },
      );
    }

    const booking = data as Booking;
    await Promise.allSettled([
      sendBookingConfirmationToClient(booking),
      sendBookingAlertToTeam(booking),
    ]);

    return NextResponse.json({ success: true });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Verification failed";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { verifyWebhookSignature } from "@/lib/razorpay";
import { supabaseAdmin } from "@/lib/supabase";
import { NextResponse } from "next/server";

export async function POST(request: Request) {
  const rawBody = await request.text();
  const signature = request.headers.get("x-razorpay-signature") ?? "";

  try {
    if (!verifyWebhookSignature(rawBody, signature)) {
      return NextResponse.json({ error: "Invalid webhook signature" }, { status: 400 });
    }

    const payload = JSON.parse(rawBody) as {
      event?: string;
      payload?: {
        payment?: { entity?: { id?: string; order_id?: string } };
        refund?: { entity?: { id?: string; payment_id?: string } };
      };
    };

    const event = payload.event;

    if (event === "payment.captured") {
      const orderId = payload.payload?.payment?.entity?.order_id;
      const paymentId = payload.payload?.payment?.entity?.id;
      if (orderId) {
        await supabaseAdmin
          .from("bookings")
          .update({
            status: "confirmed",
            razorpay_payment_id: paymentId,
            razorpay_order_id: orderId,
          })
          .eq("razorpay_order_id", orderId)
          .neq("status", "confirmed");
      }
    }

    if (event === "payment.failed") {
      const orderId = payload.payload?.payment?.entity?.order_id;
      if (orderId) {
        await supabaseAdmin
          .from("bookings")
          .update({ status: "failed" })
          .eq("razorpay_order_id", orderId)
          .eq("status", "pending_payment");
      }
    }

    if (event === "refund.processed") {
      const paymentId = payload.payload?.refund?.entity?.payment_id;
      const refundId = payload.payload?.refund?.entity?.id;
      if (paymentId) {
        await supabaseAdmin
          .from("bookings")
          .update({
            refund_status: "refunded",
            refund_id: refundId,
          })
          .eq("razorpay_payment_id", paymentId);
      }
    }
  } catch {
    // Always acknowledge so Razorpay does not retry endlessly on parse errors.
  }

  return NextResponse.json({ received: true }, { status: 200 });
}

