import { processTeamNoShowRefund } from "@/lib/refund";
import type { Booking, BookingOutcome } from "@/lib/schemas";
import { supabaseAdmin } from "@/lib/supabase";
import { NextResponse } from "next/server";

const outcomes: BookingOutcome[] = [
  "completed",
  "client_noshow",
  "cancelled",
  "pending",
  "team_noshow",
];

export async function PATCH(
  request: Request,
  { params }: { params: { id: string } },
) {
  try {
    const body = (await request.json()) as {
      outcome?: BookingOutcome;
      adjusted_in_commission?: boolean;
    };

    if (typeof body.adjusted_in_commission === "boolean") {
      const { data, error } = await supabaseAdmin
        .from("bookings")
        .update({ adjusted_in_commission: body.adjusted_in_commission })
        .eq("id", params.id)
        .select()
        .single();

      if (error || !data) {
        return NextResponse.json({ error: error?.message ?? "Update failed" }, { status: 500 });
      }
      return NextResponse.json({ booking: data });
    }

    if (!body.outcome || !outcomes.includes(body.outcome)) {
      return NextResponse.json({ error: "Invalid outcome" }, { status: 400 });
    }

    const { data: current, error: fetchError } = await supabaseAdmin
      .from("bookings")
      .select("*")
      .eq("id", params.id)
      .single();

    if (fetchError || !current) {
      return NextResponse.json({ error: "Booking not found" }, { status: 404 });
    }

    if (body.outcome === "team_noshow") {
      const result = await processTeamNoShowRefund(current as Booking);
      return NextResponse.json({ booking: result.booking, refund: result.refund });
    }

    const { data, error } = await supabaseAdmin
      .from("bookings")
      .update({ outcome: body.outcome })
      .eq("id", params.id)
      .select()
      .single();

    if (error || !data) {
      return NextResponse.json({ error: error?.message ?? "Update failed" }, { status: 500 });
    }

    return NextResponse.json({ booking: data });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Update failed";
    return NextResponse.json({ error: message }, { status: 400 });
  }
}

"use client";

import { useRouter } from "next/navigation";
import { useCallback } from "react";

type CheckoutArgs = {
  orderId: string;
  amount: number;
  key: string;
  name: string;
  email: string;
  phone: string;
  bookingId: string;
  onFailure?: (message: string) => void;
};

type RazorpaySuccess = {
  razorpay_order_id: string;
  razorpay_payment_id: string;
  razorpay_signature: string;
};

type RazorpayInstance = {
  open: () => void;
  on: (event: string, handler: (response: { error?: { description?: string } }) => void) => void;
};

type RazorpayConstructor = new (options: Record<string, unknown>) => RazorpayInstance;

function getRazorpayCtor(): RazorpayConstructor | null {
  if (typeof window === "undefined") return null;
  return (window as Window & { Razorpay?: RazorpayConstructor }).Razorpay ?? null;
}

export function useRazorpay() {
  const router = useRouter();

  const openCheckout = useCallback(
    ({
      orderId,
      amount,
      key,
      name,
      email,
      phone,
      bookingId,
      onFailure,
    }: CheckoutArgs) => {
      const RazorpayCheckout = getRazorpayCtor();
      if (!RazorpayCheckout) {
        onFailure?.("Payment checkout is still loading. Please try again.");
        return;
      }

      const checkout = new RazorpayCheckout({
        key,
        amount,
        currency: "INR",
        name: "LUXE ESTATES",
        description: "Private property viewing — ₹1,000",
        order_id: orderId,
        prefill: { name, email, contact: phone },
        theme: { color: "#c9a961" },
        handler: async (response: RazorpaySuccess) => {
          try {
            const verify = await fetch("/api/payments/verify", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                bookingId,
                razorpay_order_id: response.razorpay_order_id,
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_signature: response.razorpay_signature,
              }),
            });
            const payload = (await verify.json()) as { success?: boolean; error?: string };
            if (!verify.ok || !payload.success) {
              onFailure?.(payload.error ?? "Payment verification failed.");
              return;
            }
            router.push(`/booking/${bookingId}`);
          } catch {
            onFailure?.("Payment was captured but confirmation failed. Please contact us.");
          }
        },
      });

      checkout.on("payment.failed", (response) => {
        onFailure?.(response.error?.description ?? "Payment failed.");
      });

      checkout.open();
    },
    [router],
  );

  return { openCheckout };
}

