function upcomingDates(count = 14) {
  const dates: string[] = [];
  const cursor = new Date();
  cursor.setHours(0, 0, 0, 0);
  while (dates.length < count) {
    cursor.setDate(cursor.getDate() + 1);
    if (cursor.getDay() === 0) continue;
    const iso = cursor.toISOString().slice(0, 10);
    dates.push(iso);
  }
  return dates;
}

function formatDate(iso: string) {
  return new Date(`${iso}T12:00:00`).toLocaleDateString("en-IN", {
    weekday: "short",
    day: "numeric",
    month: "short",
  });
}

export function BookingForm({ property }: { property: Property }) {
  const { openCheckout } = useRazorpay();
  const dates = useMemo(() => upcomingDates(), []);
  const [clientName, setClientName] = useState("");
  const [clientPhone, setClientPhone] = useState("");
  const [clientEmail, setClientEmail] = useState("");
  const [viewingDate, setViewingDate] = useState(dates[0] ?? "");
  const [viewingSlot, setViewingSlot] = useState<(typeof VIEWING_SLOTS)[number]>("10:00");
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [formError, setFormError] = useState("");
  const [processing, setProcessing] = useState(false);

  async function onSubmit(event: React.FormEvent) {
    event.preventDefault();
    setFormError("");
    setErrors({});

    const parsed = bookingSchema.safeParse({
      clientName,
      clientPhone,
      clientEmail,
      propertyId: property.id,
      propertyTitle: property.title,
      viewingDate,
      viewingSlot,
      termsAccepted: termsAccepted ? true : undefined,
    });

    if (!parsed.success) {
      const fieldErrors: Record<string, string> = {};
      for (const issue of parsed.error.issues) {
        const key = String(issue.path[0] ?? "form");
        if (!fieldErrors[key]) fieldErrors[key] = issue.message;
      }
      setErrors(fieldErrors);
      return;
    }

    setProcessing(true);
    try {
      const response = await fetch("/api/bookings", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(parsed.data),
      });
      const payload = (await response.json()) as {
        bookingId?: string;
        orderId?: string;
        amount?: number;
        key?: string;
        error?: string;
      };

      if (!response.ok || !payload.bookingId || !payload.orderId || !payload.key) {
        setFormError(payload.error ?? "Could not start payment.");
        setProcessing(false);
        return;
      }

      openCheckout({
        orderId: payload.orderId,
        amount: payload.amount ?? 100000,
        key: payload.key,
        name: clientName,
        email: clientEmail,
        phone: clientPhone,
        bookingId: payload.bookingId,
        onFailure: (message) => {
          setFormError(message);
          setProcessing(false);
        },
      });
    } catch {
      setFormError("Something went wrong. Please try again.");
      setProcessing(false);
    }
  }

  return (
    <div className="grid gap-10 lg:grid-cols-[minmax(0,1fr)_20rem]">
      <form onSubmit={onSubmit} className="space-y-8" noValidate>
        <div className="grid gap-5 md:grid-cols-2">
          <Field label="Full name" error={errors.clientName} htmlFor="clientName">
            <input
              id="clientName"
              value={clientName}
              onChange={(e) => setClientName(e.target.value)}
              className="booking-input"
              autoComplete="name"
              disabled={processing}
            />
          </Field>
          <Field label="Mobile" error={errors.clientPhone} htmlFor="clientPhone">
            <input
              id="clientPhone"
              value={clientPhone}
              onChange={(e) => setClientPhone(e.target.value.replace(/\D/g, "").slice(0, 10))}
              className="booking-input"
              inputMode="numeric"
              autoComplete="tel"
              placeholder="10-digit Indian mobile"
              disabled={processing}
            />
          </Field>
          <Field label="Email" error={errors.clientEmail} htmlFor="clientEmail" className="md:col-span-2">
            <input
              id="clientEmail"
              type="email"
              value={clientEmail}
              onChange={(e) => setClientEmail(e.target.value)}
              className="booking-input"
              autoComplete="email"
              disabled={processing}
            />
          </Field>
        </div>

        <fieldset disabled={processing}>
          <legend className="mb-3 text-[0.68rem] uppercase tracking-[0.2em] text-gold-dark">
            Date
          </legend>
          <div className="flex flex-wrap gap-2">
            {dates.map((date) => (
              <button
                key={date}
                type="button"
                onClick={() => setViewingDate(date)}
                className={`border px-3 py-2 text-xs tracking-[0.12em] uppercase transition ${
                  viewingDate === date
                    ? "border-gold bg-gold text-charcoal"
                    : "border-cream-deep bg-white text-charcoal hover:border-gold"
                }`}
              >
                {formatDate(date)}
              </button>
            ))}
          </div>
          {errors.viewingDate ? (
            <p className="mt-2 text-xs text-red-700">{errors.viewingDate}</p>
          ) : null}
        </fieldset>

        <fieldset disabled={processing}>
          <legend className="mb-3 text-[0.68rem] uppercase tracking-[0.2em] text-gold-dark">
            Time slot
          </legend>
          <div className="flex flex-wrap gap-2">
            {VIEWING_SLOTS.map((slot) => (
              <button
                key={slot}
                type="button"
                onClick={() => setViewingSlot(slot)}
                className={`border px-4 py-2 text-xs tracking-[0.16em] transition ${
                  viewingSlot === slot
                    ? "border-gold bg-gold text-charcoal"
                    : "border-cream-deep bg-white text-charcoal hover:border-gold"
                }`}
              >
                {slot}
              </button>
            ))}
          </div>
        </fieldset>

        <PaymentPolicy />

        <label className="flex items-start gap-3 text-sm leading-relaxed text-ink-muted">
          <input
            type="checkbox"
            checked={termsAccepted}
            onChange={(e) => setTermsAccepted(e.target.checked)}
            className="mt-1 accent-[#c9a961]"
            disabled={processing}
          />
          <span>
            I understand the ₹1,000 fee is non-refundable and each future viewing
            requires a new ₹1,000 payment.
          </span>
        </label>
        {errors.termsAccepted ? (
          <p className="text-xs text-red-700">{errors.termsAccepted}</p>
        ) : null}

        {formError ? <p className="text-sm text-red-700">{formError}</p> : null}

        <Button type="submit" size="lg" disabled={processing}>
          {processing ? "Processing..." : "Pay ₹1,000 & Book Viewing"}
        </Button>
      </form>

      <BookingSummary
        property={property}
        viewingDate={viewingDate}
        viewingSlot={viewingSlot}
      />
    </div>
  );
}

function Field({
  label,
  htmlFor,
  error,
  className,
  children,
}: {
  label: string;
  htmlFor: string;
  error?: string;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <label htmlFor={htmlFor} className={className}>
      <span className="mb-2 block text-[0.68rem] uppercase tracking-[0.2em] text-gold-dark">
        {label}
      </span>
      {children}
      {error ? <p className="mt-2 text-xs text-red-700">{error}</p> : null}
    </label>
  );
}

