function calendarUrl(booking: Booking) {
  const start = `${booking.viewing_date.replace(/-/g, "")}T${booking.viewing_slot.replace(":", "")}00`;
  const [hours, minutes] = booking.viewing_slot.split(":").map(Number);
  const endHour = String(hours + 1).padStart(2, "0");
  const end = `${booking.viewing_date.replace(/-/g, "")}T${endHour}${String(minutes).padStart(2, "0")}00`;
  const params = new URLSearchParams({
    action: "TEMPLATE",
    text: `LUXE ESTATES viewing — ${booking.property_title}`,
    dates: `${start}/${end}`,
    ctz: "Asia/Kolkata",
    details: `Booking ref ${booking.id}. Arrive a few minutes early.`,
  });
  return `https://calendar.google.com/calendar/render?${params.toString()}`;
}

