"use client";

import { Button } from "@/components/ui/Button";
import { useRouter } from "next/navigation";
import { useState } from "react";

type Outcome = "completed" | "client_noshow" | "team_noshow";

export function BookingActions({
  bookingId,
  disabled,
}: {
  bookingId: string;
  disabled?: boolean;
}) {
  const router = useRouter();
  const [busy, setBusy] = useState<Outcome | null>(null);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  async function setOutcome(outcome: Outcome) {
    if (outcome === "team_noshow") {
      const confirmed = window.confirm(
        "Issue a full ₹1,000 refund to the original UPI because the team did not arrive within 20 minutes?",
      );
      if (!confirmed) return;
    }

    setBusy(outcome);
    setError("");
    setMessage("");
    try {
      const response = await fetch(`/api/admin/bookings/${bookingId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ outcome }),
      });
      const payload = (await response.json()) as { error?: string };
      if (!response.ok) {
        setError(payload.error ?? "Update failed");
        return;
      }
      setMessage(
        outcome === "team_noshow"
          ? "Refund of ₹1,000 has been initiated."
          : "Outcome updated.",
      );
      router.refresh();
    } catch {
      setError("Update failed");
    } finally {
      setBusy(null);
    }
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap gap-3">
        <Button
          disabled={disabled || !!busy}
          onClick={() => setOutcome("completed")}
        >
          {busy === "completed" ? "Saving..." : "Completed"}
        </Button>
        <Button
          variant="outline"
          disabled={disabled || !!busy}
          onClick={() => setOutcome("client_noshow")}
        >
          {busy === "client_noshow" ? "Saving..." : "Client No-Show"}
        </Button>
        <Button
          variant="outline"
          disabled={disabled || !!busy}
          onClick={() => setOutcome("team_noshow")}
        >
          {busy === "team_noshow" ? "Refunding..." : "Team No-Show → Refund ₹1,000"}
        </Button>
      </div>
      {message ? <p className="text-sm text-gold-dark">{message}</p> : null}
      {error ? <p className="text-sm text-red-700">{error}</p> : null}
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";

export function AdjustedToggle({
  bookingId,
  checked,
}: {
  bookingId: string;
  checked: boolean;
}) {
  const router = useRouter();
  const [value, setValue] = useState(checked);
  const [saving, setSaving] = useState(false);

  async function onChange(next: boolean) {
    setValue(next);
    setSaving(true);
    await fetch(`/api/admin/bookings/${bookingId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ adjusted_in_commission: next }),
    });
    setSaving(false);
    router.refresh();
  }

  return (
    <label className="flex items-center gap-3 text-sm text-charcoal">
      <input
        type="checkbox"
        checked={value}
        disabled={saving}
        onChange={(event) => onChange(event.target.checked)}
        className="accent-[#c9a961]"
      />
      Adjusted against commission {saving ? "(saving…)" : null}
    </label>
  );
}

