import { BookingTable } from "@/components/admin/BookingTable";
import { SiteChrome } from "@/components/SiteChrome";
import type { Booking } from "@/lib/schemas";
import { supabaseAdmin } from "@/lib/supabase";

export const dynamic = "force-dynamic";

function todayIso() {
  return new Date().toISOString().slice(0, 10);
}

export default async function AdminBookingsPage() {
  const { data, error } = await supabaseAdmin
    .from("bookings")
    .select("*")
    .order("viewing_date", { ascending: true });

  if (error) {
    return (
      <SiteChrome>
        <p className="px-5 py-16 text-red-700">{error.message}</p>
      </SiteChrome>
    );
  }

  const bookings = (data ?? []) as Booking[];
  const today = todayIso();
  const pending = bookings.filter((b) => b.status === "pending_payment");
  const upcoming = bookings.filter(
    (b) =>
      b.status === "confirmed" &&
      b.viewing_date >= today &&
      (b.outcome === "pending" || !b.outcome),
  );
  const past = bookings.filter(
    (b) =>
      b.status !== "pending_payment" &&
      (b.viewing_date < today ||
        ["completed", "client_noshow", "team_noshow", "cancelled"].includes(
          b.outcome ?? "",
        )),
  );

  return (
    <SiteChrome>
      <section className="mx-auto max-w-wide space-y-12 px-5 py-12 md:px-8">
        <div>
          <p className="text-[0.68rem] uppercase tracking-[0.28em] text-gold-dark">
            Operations
          </p>
          <h1 className="mt-3 font-serif text-4xl text-charcoal">Bookings</h1>
        </div>
        <Section title="Pending Payment" bookings={pending} />
        <Section title="Upcoming Viewings" bookings={upcoming} />
        <Section title="Past Viewings" bookings={past} />
      </section>
    </SiteChrome>
  );
}

function Section({ title, bookings }: { title: string; bookings: Booking[] }) {
  return (
    <div>
      <h2 className="mb-4 font-serif text-2xl text-charcoal">{title}</h2>
      <BookingTable bookings={bookings} />
    </div>
  );
}

